'use strict';

// MODULES //

var tape = require( 'tape' );
var Complex128Array = require( '@stdlib/array/complex128' );
var ndarray = require( '@stdlib/ndarray/base/ctor' );
var znancount = require( './../lib' );


// FUNCTIONS //

/**
* Returns a one-dimensional ndarray.
*
* @private
* @param {Complex128Array} buffer - underlying data buffer
* @param {NonNegativeInteger} length - number of indexed elements
* @param {integer} stride - stride length
* @param {NonNegativeInteger} offset - index offset
* @returns {ndarray} one-dimensional ndarray
*/
function vector( buffer, length, stride, offset ) {
	return new ndarray( 'complex128', buffer, [ length ], [ stride ], offset, 'row-major' );
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof znancount, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 1', function test( t ) {
	t.strictEqual( znancount.length, 1, 'has expected arity' );
	t.end();
});

tape( 'the function computes the number of non-`NaN` elements in a one-dimensional ndarray', function test( t ) {
	var x;
	var v;

	x = new Complex128Array( [ 1.0, 2.0, NaN, NaN, 3.0, 4.0, NaN, 5.0, 6.0, NaN, 0.0, 0.0 ] ); // eslint-disable-line max-len
	v = znancount( [ vector( x, 6, 1, 0 ) ] );
	t.strictEqual( v, 3, 'returns expected value' );

	x = new Complex128Array( [ 1.0, -2.0, 3.0, -4.0 ] );
	v = znancount( [ vector( x, 2, 1, 0 ) ] );
	t.strictEqual( v, 2, 'returns expected value' );

	x = new Complex128Array( [ -0.0, 0.0, 0.0, -0.0 ] );
	v = znancount( [ vector( x, 2, 1, 0 ) ] );
	t.strictEqual( v, 2, 'returns expected value' );

	x = new Complex128Array( [ NaN, NaN ] );
	v = znancount( [ vector( x, 1, 1, 0 ) ] );
	t.strictEqual( v, 0, 'returns expected value' );

	x = new Complex128Array( [ NaN, NaN, NaN, NaN ] );
	v = znancount( [ vector( x, 2, 1, 0 ) ] );
	t.strictEqual( v, 0, 'returns expected value' );

	t.end();
});

tape( 'the function considers an element to be `NaN` if either its real or imaginary component is `NaN`', function test( t ) {
	var x;
	var v;

	x = new Complex128Array( [ NaN, 1.0, 1.0, NaN, NaN, NaN, 1.0, 1.0 ] );
	v = znancount( [ vector( x, 4, 1, 0 ) ] );
	t.strictEqual( v, 1, 'returns expected value' );

	t.end();
});

tape( 'if provided an empty vector, the function returns `0`', function test( t ) {
	var x;
	var v;

	x = new Complex128Array( [] );

	v = znancount( [ vector( x, 0, 1, 0 ) ] );
	t.strictEqual( v, 0, 'returns expected value' );

	t.end();
});

tape( 'if provided a vector containing a single non-`NaN` element, the function returns `1`', function test( t ) {
	var x;
	var v;

	x = new Complex128Array( [ 1.0, 2.0 ] );

	v = znancount( [ vector( x, 1, 1, 0 ) ] );
	t.strictEqual( v, 1, 'returns expected value' );

	t.end();
});

tape( 'the function supports one-dimensional ndarrays having non-unit strides', function test( t ) {
	var x;
	var v;

	x = new Complex128Array([
		1.0,  // 0
		2.0,  // 0
		9.0,
		9.0,
		NaN,  // 1
		1.0,  // 1
		9.0,
		9.0,
		3.0,  // 2
		4.0,  // 2
		9.0,
		9.0,
		5.0,  // 3
		6.0,  // 3
		9.0,
		9.0
	]);

	v = znancount( [ vector( x, 4, 2, 0 ) ] );

	t.strictEqual( v, 3, 'returns expected value' );
	t.end();
});

tape( 'the function supports one-dimensional ndarrays having negative strides', function test( t ) {
	var x;
	var v;

	x = new Complex128Array([
		1.0,  // 3
		2.0,  // 3
		9.0,
		9.0,
		NaN,  // 2
		1.0,  // 2
		9.0,
		9.0,
		3.0,  // 1
		4.0,  // 1
		9.0,
		9.0,
		5.0,  // 0
		6.0,  // 0
		9.0,
		9.0
	]);

	v = znancount( [ vector( x, 4, -2, 6 ) ] );

	t.strictEqual( v, 3, 'returns expected value' );
	t.end();
});

tape( 'the function supports one-dimensional ndarrays having non-zero offsets', function test( t ) {
	var x;
	var v;

	x = new Complex128Array([
		NaN,
		NaN,
		1.0,  // 0
		2.0,  // 0
		NaN,
		NaN,
		NaN,  // 1
		3.0,  // 1
		0.0,
		0.0,
		3.0,  // 2
		4.0,  // 2
		NaN,
		NaN,
		5.0,  // 3
		6.0   // 3
	]);

	v = znancount( [ vector( x, 4, 2, 1 ) ] );
	t.strictEqual( v, 3, 'returns expected value' );

	t.end();
});
